def run_inproc(doc):
    """Call the project's run() directly (fast, in-process)."""
    import importlib, sys as _sys
    if PROJ not in _sys.path:
        _sys.path.insert(0, PROJ)
    import main as m
    importlib.reload(m)
    try:
        return m.run(doc)
    except Exception as e:
        import traceback; traceback.print_exc()
        return {'error': 'input'}
